// Calls unchanged official 1.21.11 AABB.clip/contains and inherited pick radius.
// No world/server is started. Numeric inputs are generated by this driver.
import com.google.gson.*;
import java.lang.reflect.*;
import java.nio.file.*;
import java.util.*;

public final class ExportEntityTargetRays {
    static Object vector(Constructor<?> c, double[] a) throws Exception {
        return c.newInstance(a[0], a[1], a[2]);
    }
    static double[] values(Object v) throws Exception {
        Class<?> c = v.getClass();
        return new double[]{c.getField("g").getDouble(v), c.getField("h").getDouble(v), c.getField("i").getDouble(v)};
    }
    static String[] bits(double[] values) {
        return Arrays.stream(values).mapToObj(v -> Long.toUnsignedString(Double.doubleToRawLongBits(v),16)).toArray(String[]::new);
    }
    public static void main(String[] args) throws Exception {
        Class.forName("w").getMethod("a").invoke(null);
        Class.forName("amv").getMethod("a").invoke(null);
        Class<?> box = Class.forName("fth"), vec = Class.forName("ftm");
        Constructor<?> makeBox = box.getConstructor(double.class,double.class,double.class,double.class,double.class,double.class);
        Constructor<?> makeVec = vec.getConstructor(double.class,double.class,double.class);
        Method clip = box.getMethod("b",vec,vec), contains = box.getMethod("d",vec);
        JsonObject result = new JsonObject();
        JsonArray radii = new JsonArray();
        Class<?> unsafeClass = Class.forName("sun.misc.Unsafe");
        Field field = unsafeClass.getDeclaredField("theUnsafe"); field.setAccessible(true);
        Object unsafe = field.get(null);
        Method allocate = unsafeClass.getMethod("allocateInstance", Class.class);
        Method radius = Class.forName("cgk").getMethod("ci");
        for (String[] type : new String[][]{{"player","axg"},{"cow","cuh"},{"pig","cxb"},{"zombie","dcn"}}) {
            JsonObject row = new JsonObject(); row.addProperty("type",type[0]);
            row.addProperty("radius",(Float)radius.invoke(allocate.invoke(unsafe,Class.forName(type[1]))));
            radii.add(row);
        }
        result.add("pick_radii",radii);
        Object range = Class.forName("jd").getMethod("a").invoke(Class.forName("cis").getField("l").get(null));
        Class<?> ranged = Class.forName("ciu");
        result.add("entity_range_limits",new Gson().toJsonTree(new double[]{
            (Double)ranged.getMethod("d").invoke(range),(Double)ranged.getMethod("e").invoke(range)}));
        JsonArray cases = new JsonArray();
        for (double offset : new double[]{0.,-16.,29999990.})
        for (double scale : new double[]{.0625,1.,1.3,16.})
        for (int axis=0; axis<3; axis++)
        for (int sign : new int[]{-1,1})
        for (double edge : new double[]{.5,0.,1.,1.+.5e-7,1.+2e-7})
        for (double length : new double[]{0.,1.,2.,3.}) {
            double[] lo={offset,offset,offset}, hi={offset+scale,offset+scale,offset+scale};
            double[] start={offset+edge*scale,offset+edge*scale,offset+edge*scale};
            start[axis]=sign>0 ? offset-scale : offset+2*scale;
            double[] end=start.clone(); end[axis]+=sign*length*scale;
            Object bounds=makeBox.newInstance(lo[0],lo[1],lo[2],hi[0],hi[1],hi[2]);
            add(cases, bounds, start,end,makeVec,clip,contains);
        }
        // Half-open inside, min/max faces, zero rays and diagonal entry ties.
        Object unit=makeBox.newInstance(0.,0.,0.,1.,1.,1.);
        for(double x:new double[]{0.,.5,1.}) for(double y:new double[]{0.,.5,1.})
        for(double z:new double[]{0.,.5,1.}) for(double[] end:new double[][]{{0.,0.,0.},{2.,2.,2.},{-1.,-1.,-1.}})
            add(cases,unit,new double[]{x,y,z},end,makeVec,clip,contains);
        result.add("cases",cases);
        Files.writeString(Path.of(args[0]),new GsonBuilder().serializeNulls().create().toJson(result)+"\n");
    }
    static void add(JsonArray cases,Object box,double[] start,double[] end,Constructor<?> makeVec,Method clip,Method contains) throws Exception {
        Object from=vector(makeVec,start), to=vector(makeVec,end);
        Optional<?> hit=(Optional<?>)clip.invoke(box,from,to);
        boolean inside=(Boolean)contains.invoke(box,from);
        JsonObject row=new JsonObject(); Gson json=new Gson();
        double[] bounds=new double[6]; String[] fields={"a","b","c","d","e","f"};
        for(int i=0;i<6;i++) bounds[i]=box.getClass().getField(fields[i]).getDouble(box);
        row.add("bounds",json.toJsonTree(bounds)); row.add("start",json.toJsonTree(start)); row.add("end",json.toJsonTree(end));
        row.addProperty("inside",inside);
        row.add("point",hit.isPresent()?json.toJsonTree(values(hit.get())):inside?json.toJsonTree(start):JsonNull.INSTANCE);
        row.add("bounds_bits",json.toJsonTree(bits(bounds)));
        row.add("start_bits",json.toJsonTree(bits(start)));
        row.add("end_bits",json.toJsonTree(bits(end)));
        row.add("point_bits",hit.isPresent()?json.toJsonTree(bits(values(hit.get()))):inside?json.toJsonTree(bits(start)):JsonNull.INSTANCE);
        cases.add(row);
    }
}
